const rows = {
  entry: ['拜师之后，先学哪门本事', '闻竹带你看过练剑场、阵法课和药圃。程照雪负责教剑，沈砚在药圃做事。你可以先选一门本事，日后仍会有学习其他技艺的机会。', ['向程照雪学剑，先从收剑和护身练起。','跟闻竹学习阵法，练习识路与修补护阵。','到药圃认药、照料药苗，再学炼丹。']],
  lesson: ['沈砚烧坏了药圃', '沈砚为了赶考核，擅自借用丹炉，火烧到了药圃。程照雪想替他担责，闻竹要求你们先向等药的山民解释。你知道经过，现在要决定怎样处理。', ['陪沈砚去说明经过，一起补种药苗。','先想办法补上缺药，再处理责任。','向闻竹说明你知道的经过。']],
  mission_sword: ['渡口有人扣住了孩子', '散修截住运药的渡船，把一个孩子当作人质。程照雪在岸边掩护你，对方的飞刃已经出鞘。先把孩子带到安全地方，还是寻找动手的机会？', ['沿河寻找绕到对方身后的路。','提出交路费，争取先放走孩子。','对方靠得很近，出剑可能引来飞刃。']],
  mission_array: ['山下的旧暗渠还能修', '你随师长检查山下护阵，发现一条通向渡口的废弃暗渠。山民不知道哪里能安全通行，程照雪也担心暗渠被外人利用。你可以先做一项修整。', ['修复暗渠，自己留一份图。','在旧路设置警铃，提醒巡山弟子。','带山民认路，让他们能自行出山。']],
  mission_alchemy: ['药不够同时送往两处', '村里有人染上瘴病，一名受伤修士也来求药。现有药材不够两处一起用。修士说他能联系药商，但村里的病人未必等得起。', ['先让村民用药，再寻找替代药材。','修士承诺联系药商，回信还未到。','新药方未经验证，需要谨慎试药。']],
  cave: ['宗门让你选择住处', '你可以领一处洞府了。山顶靠近巡山路线，药谷有人共灶，旧阵台便宜但需要修补。程照雪和沈砚来帮你看屋，你也可以继续借住。', ['山顶便于练剑和守望。','药谷离来求药的人近。','旧阵台漏雨，附近有废弃的出山路。','先借住，把积蓄留在身边。']],
  omen: ['镜火盟的战舟出现在北面', '商旅说镜火盟正在征用附近宗门的弟子，几处关卡已经换旗。闻竹收到借用山门大阵的要求，但尚未答应。你可以撤人、打听消息或联系旧友。', ['先安排不擅斗法的人离山。','营地戒备严，需要躲开巡逻。','把已知消息传出去，请旧友留意。']],
  war_council: ['山门开始准备应敌', '镜火盟战舟停在山外，护阵已经出现裂纹。闻竹守主阵，程照雪带弟子巡山。暗渠、合击和伤药都还缺人手，你要先做哪一项？', ['接通暗渠，检查撤离出口。','和程照雪练习应敌与撤剑口令。','整理伤药，分给准备撤离的人。']],
  siege: ['敌人攻进了山门', '有人从内部打开护阵，药谷起火。闻竹被困在主阵，沈砚困在藏经阁，钟楼还有弟子名单与阵图。程照雪守住岔路，你只能先去一处。', ['先去主阵找闻竹。','先去藏经阁找沈砚。','先把名单、阵图和附近弟子带出去。','敌人已经逼近，再守一刻会让你陷入包围。']],
  refugees: ['渡口的幸存者缺药少粮', '你们在望渡镇落脚，船、米和伤药都不足。程照雪照顾伤员，白渡说旧阵台还连着通往其他大陆的界门。眼前要先安置人，还是寻找新的去处？', ['留下治伤、修器，筹措路费。','请熟悉的船夫帮忙接应。','带着追兵走向官道，让其他人先藏好。']],
  hunter: ['宋却追到了渡口', '镜火盟修士宋却堵住你。他的剑已断了一半，随身家书写着家人急需路费。他要求交出追猎标记，附近没有同门能立刻赶来。', ['先和他谈家人的去路。','留下假身，寻找河底出口。','他的飞剑仍能伤人，需要正面应战。']],
  foundation: ['准备尝试筑基', '你已练习炼气多年，最近运功时真气不再轻易散掉。白渡检查过你的经脉，建议安排一次筑基修行。可以借药调养、在修阵中慢慢积累，也可以冒险提前尝试。', ['请白渡照看药与闭关住处。','先替镇民修阵，积累后再尝试。','你的经脉尚未完全稳定，强行破关可能受伤。']],
  gate: ['寻找另一片大陆的落脚处', '白渡修好了跨大陆的界门。镜火盟仍在追查离宗弟子，你打算先找能住下、能谋生的地方。各地环境不同，到了之后还要结识当地人。', ['海港需要懂阵法和疗伤的人。','荒原驿站缺水，匠人靠地火谋生。','浮岛书院需要修桥、护船和照看药圃。']],
  landing_tide: ['临潮港需要人手', '你在临潮港找到落脚处。嵇萝是熟悉航路的筑基修士，她带你见船主和潜水人。港口不白给住处，你需要先做一项当地人需要的工作。', ['随船认暗流与灯塔。','留在岸上为潜水人疗伤。','沉船附近有断链，水下情况不明。']],
  tide_wreck: ['沉船里困着幼兽', '嵇萝带你查看沉船，发现笼里困着一只幼兽，旁边阵台放着定魂珠。定魂珠能在修行中帮助安定神识。笼锁与阵台相连，需要决定先处理什么。', ['先拆笼锁，观察阵台变化。','先取珠，再告诉守港人笼的位置。','先记录锁链与界门的阵纹。']],
  tide_storm: ['风暴中的船还没靠岸', '临潮港遭遇风暴，外海还有船，岸上的居民也需要避难。嵇萝正在准备救援舟，港阵有几处无法接通。你能先承担一项工作。', ['先修外港护阵。','和嵇萝出海寻找船只。','先带岸上居民往内陆走。']],
  landing_ember: ['荒原驿站缺水', '你到了烬原驿站。嵇萝向你介绍当地匠人：这里靠地火修器，水却比灵石难买。住下来之前，你需要帮他们解决水源或护送的问题。', ['用引雨石尝试给井补水。','和井工一起寻找地下水。','随商队到有水的下一处驿站。']],
  ember_caravan: ['妖兽追着商队', '商队带着一只被锁住的幼兽，身后沙尘里有成年妖兽追来。嵇萝让老人孩子先走，守城人则要求把幼兽送进城阵。你得先处理追击。', ['解开锁链，给幼兽留路。','联系守城人接管兽笼。','沙尘中看不清妖兽的位置，挡路可能受伤。']],
  ember_ruins: ['旧炼器炉需要修复', '城下有一座损坏的炼器炉，原本供给全城地火。匠人缺月白矿，正在招人修炉。炉心是能持续生火的法宝，也可用于修炼与维持大阵。', ['带矿料和匠人一起修炉。','留在炉城做工，学习养炉。','把结构图带给浮屿书院研究。']],
  landing_sky: ['浮岛之间的桥坏了', '浮屿的岛会随季风缓慢移动，桥和船路需要不断调整。嵇萝带你向书院登记，院里急缺修桥、迁药和护船的人。', ['先修桥，检查两端落脚处。','帮书院迁移药圃。','跟着书船熟悉航路。']],
  sky_archive: ['藏书岛正在漂走', '一座藏书岛偏离了航路，岛上还有藏书人和被锁住的幼兽。书船载不了所有东西，嵇萝准备先接人，院里又急着找回一页界门图。', ['先接藏书人上船。','先解幼兽的锁，看它能否带船。','残桥随时可能断，取书需要深入。']],
  sky_fall: ['书院岛屿开始下沉', '浮岛护阵损坏，书院正在下沉。你修过的桥还能通行，嵇萝安排渡船。人和书都需要撤走，但时间已经不多。', ['尝试把各座桥接成承重阵。','按船位分批接走人和书。','断桥正在坍塌，独自支撑很危险。']],
  crossroads: ['在异乡站稳脚跟之后', '你已有住处，也认识了能互相照应的人。嵇萝带来附近遗迹的消息，你也可以去其他大陆求学或做工。出门前先决定往哪里走。', ['先查看附近遗迹的入口。','去荒原向匠人求教。','去书院补全跨界航图。']],
  visit_tide: ['潜水人的船被扣住了', '你来到临潮港，发现潜水人与船主为泊船费争执，船上的孩子还没能上岸。失控的潮阵也阻住了另一条航路。', ['先说明情况，再检查潮阵。','先垫付泊船费。','绕开争执，向潜水人打听航图。']],
  visit_ember: ['匠人不愿拆掉唯一的炉心', '烬原匠人愿意教你造炉，但不能把维持全城的炉心拆走。你可以参与造第二颗、给旧炉补料，或先带走图纸。', ['留在炉坊，从锻料开始学。','先补足旧炉需要的矿料。','先学习结构和火候。']],
  visit_sky: ['航图漏了一座有人住的岛', '书院的新航图没有收录一座偏远小岛，岛民因此收不到药与粮。你已找到他们的信号，接下来可以测路、学习周期或筹船。', ['绕行小岛，记录安全船路。','先向书院学季风与界门周期。','先筹船送补给。']],
  relic_door: ['遗迹入口刻着献祭碑文', '嵇萝陪你查看遗迹。碑文声称必须留下一个活人，阵法才能开门，但旁边有旧修士留下的出口标记。你可以研究旧图、留在外缘修炼，或试着破碑。', ['照旧图核对出口。','先在外缘观察火候和阵法。','碑后藏着阵火，强拆可能遭到反击。']],
  golden: ['开始准备结丹', '多年修行后，你发现真气能够凝聚，但还无法长久维持。嵇萝请药师检查经脉，建议借定魂珠安定神识，再尝试结丹。你也可以先继续过筑基的日子。', ['借定魂珠调养，安排守关的人。','尚未充分调养，提前尝试可能伤到经脉。','先处理住处、航路和人情。']],
  golden_repair: ['结丹失败后，先治伤', '你没能凝成金丹，经脉也受了伤。嵇萝找来药师，建议先休养。你可以用行囊里的药调养、请外地药师会诊，或暂时放下结丹。', ['先按药方长期调养。','先稳住伤势，继续现有生活。','把病状和药方寄给各地药师。']],
  beast_attack: ['天外妖兽袭击了城池', '巨兽从界门出现，撞坏城外护阵。嵇萝正在接应居民，地下避难所和跨界船都还可用。它身上的锁链与你见过的兽笼相似。', ['用幼兽留下的鳞片尝试接近。','先开界门，接走居民。','护阵已经受损，正面抵挡仍有危险。','先带药和孩子去地下。']],
  beast_wake: ['废墟下还有求救声', '袭击过后，城里有房屋倒塌，补给点也被埋住了。仍有人困在废墟下，嵇萝与当地药师在寻找他们。你可以挖通救援路，或先建立补给和联络。', ['先找仍在回应的被困者。','修好联络阵，联系外地援手。','整理药与食物，等危险区域平静。']],
  letter: ['师姐寄来了故乡消息', null, ['先筹备回去救人。','带上战书，也先查清敌人的位置。','先找能接纳幸存者的异乡住处。']],
  retreat: ['归乡之前，怎样准备', '你已知道故乡有人被困。嵇萝建议先检查援军、航路和自身伤势。你可以演练救援、尝试元婴，也可以现在启程；故乡的时间仍在流逝。', ['把盟友、船路和撤离安排接起来。','用炉心准备闭关，提前安排收信。','先带现有本领和物资出发。']],
  beacon: ['闭关中收到了急报', null, ['现在出关，联系救援。','托已答应帮忙的人先去。','先停下修炼，把炉心用于救援。']],
  assemble: ['出发前核对援手', '愿意帮忙的人陆续回信，但船、人手和物资都有限。嵇萝与你核对撤退顺序。镜火盟也已知道有人准备归来，你需要定下行动重点。', ['先列被困者名单和撤离顺序。','把旧暗渠与航图接成路线。','让盟主把注意力放到你身上。']],
  return_gate: ['敌人守住了归乡界门', null, ['与宋却谈好营中人的退路。','寻找能绕开正面战阵的通道。','门前已布下伏击，强闯可能伤到同行者。']],
  home_ruins: ['回到旧山门', null, ['先去山下见仍在的人。','先查地牢和旧暗渠。','先到旧墓与药圃看一看。']],
  enemy_terms: ['盟主要求你接管供奉', '镜火盟主提出归还旧山门，条件是你继续把年轻弟子送去域外充当阵法的活人能源。会面期间，山下还有人等待撤离。', ['拒绝交人，准备救援。','先拖住会面，寻找换防机会。','放下山门，先接走愿意离开的人。']],
  rescue: ['地牢里的人还在等', null, ['检查阵钉和地牢出口。','用炉心替换维持牢阵的能源。','硬拆枷锁会引来阵法反击。']],
  return_battle: ['镜火盟打开了域外主门', '敌人打开域外主门，新的巨兽与战舟开始出现。程照雪接应撤离者，嵇萝守住另一端退路。你要决定封门、联合援手、正面交战或掩护撤离。', ['用航图与旧线索寻找主门弱点。','让已到场的盟友各守一处阵位。','真身已经降临，独战可能无法脱身。','先保住撤离队的出口。']],
  last_rescue: ['最后一批人还没离山', '敌人控制山门，还有一批弟子被堵在山下。你掌握旧暗渠，也可能有船或界门锚可用。撤离需要有人组织，两岸都要接应。', ['检查界门两岸的通路。','沿暗渠分批护送。','燃尽自身寿元维持出口。']],
  rebuild: ['大战过后，怎样安顿', '战事暂歇，旧山门需要修复，幸存者也需要住处和生计。有人想重开宗门，有人想连接各地，有人只想休养种药。你要参与哪一条路？', ['先恢复教学和住处。','把这里办成各地共同使用的驿站。','先在山下照看药田与伤员。']],
  final_choice: ['往后的日子怎样过', '救援和安顿告一段落。年轻弟子已能接手部分事务，你也可以把时间留给教学、远行或自己的生活。', ['留在这里教人。','与愿意同行的人再出门。','先检查跨界归路。']],
  far_cost: ['接走故乡的人需要船与接应', '你在异乡找到安置处，但故乡的人还没有到。有人腿脚不便，有人带着孩子，不能只寄一封邀请。你需要实际组织接送。', ['使用界门，安排两岸接应。','找船主与愿意护送的人。','亲自回去，带他们走熟悉的路。']],
  far_finale: ['新的住处，新的生活', '幸存者在异乡安顿下来。有人想学修行，有人更愿意种田行医。你可以开学舍、分田地，或把照料交给可靠的人继续远行。', ['先教认字、调息和护身。','先安排田地与药圃。','先与接手的人交代清楚。']],
  urgent_message: ['远方送来了急讯', null, ['收拾行囊，放下未完成的事，准备赶路。','联系曾答应援助的人，送出物资。','留一封回复，继续当前的路。']],
  childhood: ['六岁，开始学一门本事', null, ['先跟先生认字。','到药铺帮忙，记药草。','跟旅人学看路与护身。']],
  family_claim: ['家里遇到了难处', null, ['寄钱回去，请家人先安排退路。','拿着契约打听能出面的人。','请家人先搬到便宜的住处。']],
  devouring_night: ['妖兽从界门吞进山门', '域外巨兽从界门出现，吞掉一段护山阵。镜火盟战舟趁乱围住外门。闻竹撑着残阵，沈砚困在药库，程照雪把仍能走的路指给你。', ['先接闻竹沿外门走。','拿着名单和阵图带人出山。','裂口仍在扩大，独自阻挡可能丧命。']],
  fall_decree: ['宗门被强行征用', '镜火盟要求征走年轻弟子，闻竹拒绝交人后被锁进主阵。程照雪带来换防消息，沈砚也被扣住。旧宗门已经无法照常开课，你得决定先做什么。', ['趁换防寻找闻竹。','先拿名单，接走愿意离开的人。','拿积蓄和护符与守卫谈放人。']],
  trial_invitation: ['回风谷准备开门', '闻竹公布回风谷这一届采药安排：先采药坡成熟灵草，再查古坛旧阵。外门有人接应，深入后要自己记路。陶宁懂辨药和警戒符，问你愿不愿与他结伴。', ['先买补给，在外门登记姓名。','留在外门接应这一届弟子。']],
  trial_entry: ['药坡的引路绳被割断了', '你与陶宁沿药坡扎营，发现前队割断了引路绳。附近有通往古坛的脚印，也有一座尚未稳定的风桥。先修路，还是尝试追上前队？', ['先修绳索，把营地连回外门。','循脚印检查侧门。','桥上已有断绳，陶宁劝你等风停。']],
  trial_chasm: ['陶宁跌进了石缝', '断涧的旧阵突然启动，陶宁掉进石缝，仍能呼救。前队遗落的宝匣在另一侧，通往古坛的路也快要关闭。你无法同时赶到所有地方。', ['先找落脚点，放绳下去。','先去宝匣处，把坐标送往外门。','救人后沿原路撤出。']],
  trial_core: ['古坛要求留下一个活人', null, ['照来时留下的路标检查阵纹。','夺灵阵仍在运转，独闯可能回不来。','不再深入，沿旧路返回。']],
  trial_return: ['返回外门，报出同行者的名字', null, ['抄出路线，交给接应的人。','留下原图，报出最后见过的坐标。']],
  trial_echo: ['陶宁送来了当年的姓名牌', null, ['把路线和物资寄给他。','教当地弟子看懂路线，再组织接应。','说明这次去不了，交出已知坐标。']],
  cavern_invitation: ['沉星洞府传来求援消息', '嵇萝带来守门人的求援：前一队勘探者失联，墙上的旧路线与回风谷阵纹相似。你们已经核实入口，但深处路线不全。此行先找失联者，再查看旧炼器炉。', ['和嵇萝登记，准备药、水和灯。','留在补给点为回来的人修器。']],
  cavern_fork: ['洞内的路分成三支', '你与嵇萝找到前队的营地，粮袋已空。玉壁旁留下求救记号，地火源通向旧炉，深处还有一道正在移动的门。先走哪一条？', ['循求救记号，核对出口。','在地火源搭炉，先解决火与补给。','移动的阵门可能把人隔在两侧。']],
  cavern_heart: ['宝物与出口连在同一座阵上', '阵室里有定魂珠和炉心，取走它们可能改变出口。嵇萝检查最后的药与水，催你先核对退路。可以研究改阵、留下灵石供能、强取或撤出。', ['试着用钥调整阵线。','留下灵石，先取其中一件。','门正在移动，强穿可能被留在里面。','先带同行者离开。']],
  cavern_exit: ['洞口有人盘问归来者', null, ['把出口路线交给当地守门人。','不公开行囊，先找另一处住屋。']],
  outer_invitation: ['有人找到失联队伍的定位信号', '嵇萝与你核对过星图，守门人也完成了定位阵。域外失联修士的信号再次出现，这次可以尝试跨界接应。需要携带定位物，并约好另一端收信的人；门后没有完整地图。', ['带上定位物和补给，与嵇萝同行。','留在门外照看定位阵。']],
  outer_drift: ['漂流碎陆上出现了求救灯', '你们沿定位绳前行，看到一座残城发出求救灯号。另一边有强烈的法宝波动，但那片区域留着大能布下的猎阵。先去接人、稳住退路，还是追踪法宝？', ['先到残城询问活着的人。','把界门锚留在安全碎陆上。','猎阵里没有完整坐标，可能切断归路。']],
  outer_heart: ['残城靠界心维持稳定', '你们查明残城靠界心维持稳定，取走它会让城塌落。大能的使者堵住出口，要求交人。嵇萝与你核对星图：可以改阵、另留灵源、迎战或返回。', ['按已知星图重新接通能源。','把炉心留给残城供能。','使者后方还藏着大能真身，独战可能丧命。','先沿定位绳返回。']],
  outer_return: ['回到故乡之外的城镇', null, ['公开归来者名单，与守门人共同保管路线。','先换住处，少向外人提起行囊。']],
  treasure_claim: ['有人扣住了补给船', null, ['联系曾共同历险的人。','交出对方索要的物件，先放船离开。','屋外已布下战阵，独战可能丧命。']],
  last_vow: ['最后一程，选择自己的去向', '你已走过修行、远行与救援，年轻人能够接手一些事务。接下来可以继续问道、守护诸界，也可以交代好遗物，结束争夺。', ['准备迎接最后的道劫，仍有生命危险。','留下界心，承担维持通路的职责。','把遗物和牵挂逐一交代。','留下地图，再向远处走。']],
};
export function makeReadable(nodes) {
  return Object.fromEntries(Object.entries(nodes).map(([id, node]) => {
    const row = rows[id];
    if (!row || row[2].length !== node.choices.length) throw new Error('Missing readable scene: ' + id);
    const text = row[1] || ((state) => contextualScene(id,node,state));
    return [id, { ...node, title: row[0], text:s=>adaptCompanion(typeof text==='function'?text(s):text,s), choices: node.choices.map((c, i) => ({ ...c, hint: row[2][i], effects:s=>safePeople(typeof c.effects==='function'?c.effects(s):c.effects,s), reply:s=>adaptCompanion(typeof c.reply==='function'?c.reply(s):c.reply,s), ...(c.check?{check:{...c.check,failure:s=>safePeople(typeof c.check.failure==='function'?c.check.failure(s):c.check.failure,s),failText:s=>adaptCompanion(typeof c.check.failText==='function'?c.check.failText(s):c.check.failText,s)}}:{}), ...(id==='foundation'&&c.id==='medicine'?{label:'用随身药材调养，尝试筑基'}:{}), ...(id==='retreat'&&c.id==='nascent'?{cost:s=>s.life?.feedback?{items:['ember_engine']}:{}}:{}) })) }];
  }));
}
function safePeople(input,s){
 const effect=JSON.parse(JSON.stringify(input||{}));
 for(const id of Object.keys(effect.people||{}))if(s.people[id]?.status==='dead')delete effect.people[id];
 return effect;
}
function adaptCompanion(text,s){
 return String(text||'').replaceAll('嵇萝',s.people.ally.status==='dead'?'接应的修士':'嵇萝');
}
function contextualScene(id,node,s) {
  const master=s.people.master.status, mate=s.people.trialmate.status;
  if(id==='letter')return '程照雪来信：镜火盟仍占着旧山门，'+(master==='dead'?'闻竹已离世，还有同门被困在牢阵。':master==='captured'?'闻竹被困在主阵，还有同门被扣住。':'闻竹与幸存者住在山下，仍有人被困在旧宗门。')+'她寄来最后见到他们的位置，问你是否愿意组织救援。';
  if(id==='beacon')return '程照雪发来急报：山下伤员需要转移，旧阵还能坚持'+(s.world.masterDeadline===null?'一段时间':Math.max(0,Math.ceil((s.world.masterDeadline-s.month)/12))+'年')+'。闭关还没有完成，你要现在出关，还是托人先帮忙？';
  if(id==='return_gate')return '镜火盟守住归乡界门。'+(s.flags.mercy?'宋却带来换防消息，愿意帮你关掉一侧敌阵。':'白渡找到能绕开战舟的通路，但需要定位物稳定出口。')+'同行者正在等你的安排。';
  if(id==='home_ruins')return '你来到旧洞府，屋顶已塌。程照雪带你查看幸存者的住处。'+(master==='dead'?'她告诉你闻竹墓地的位置。':master==='captured'?'她说闻竹仍被困在主阵，建议先查清守卫与出口。':'闻竹在山下照看伤员，等你过去。')+'眼前的人和房屋都需要安顿。';
  if(id==='rescue')return '你找到弟子名单上被困者的牢房。'+(master==='captured'?'闻竹仍被锁在维持牢阵的位置。':'闻竹不在牢阵里，其他同门仍被扣住。')+'程照雪守着撤离路，等你打开出口。';
  if(id==='childhood')return s.birth.family==='clan'?'六岁，家族长辈教你辨认护符，堂亲带你看药田。家里准备让你先学一门本事。':s.birth.family==='noble'?'六岁，家里请来先生。你也可以到药铺或跟随商队学一些出门的本事。':'六岁，家人带你到药田，村里先生也愿意教你认字。你开始学着做一点自己的事。';
  if(id==='family_claim')return '家中来信：'+(s.birth.family==='clan'?'镜火盟要求交出护符与灵田，家人正在找避难的地方。':'商路断了，铺子收到追债契约，家人担心旧屋也保不住。')+'他们问你能否寄钱，或联系能出面的人。';
  if(id==='trial_core')return '你来到古坛，发现阵法会抽走人的法力，碑文要求留下一名同伴。'+(mate==='missing'?'陶宁尚未找到，你留着他最后的位置。':mate==='dead'?'陶宁已经离世，遗物在你行囊中。':'陶宁正在检查来时的路。')+'你可以研究旧路、独自破阵或返回。';
  if(id==='trial_return')return '你沿路标回到'+(s.flags.sectLost?'渡口的幸存者营地':'外门')+'，接应的人开始点名。'+(mate==='dead'?'你交代陶宁离世的地点，带回了遗物。':mate==='missing'?'陶宁仍未归来，你报出最后的位置。':'陶宁也到了，你们核对了这次的路图。')+'现在要决定怎样保管路线。';
  if(id==='cavern_exit')return '你返回洞口补给点，陌生修士拦住归来者，盘问洞里的宝物。'+(s.people.ally.status==='dead'?'嵇萝没有回来，你向接应人交代了她的最后经历。':'嵇萝在补给点交接路图。')+'你可以请当地人共同守住出口，或少向外人提起行囊。';
  if(id==='outer_return')return '你回到跨界接应阵，守门人登记归来者。'+(s.people.ally.status==='dead'?'嵇萝已经离世，她的遗物由你带回。':'嵇萝也回来，把最新星位交给守门人。')+'外面有人打听界心的消息，你要怎样处理路图与行囊？';
  if(id==='treasure_claim')return '索宝修士循着'+(s.inventory.includes('mirror_heart')?'界心':s.inventory.includes('ember_engine')?'炉心':'沉星钥')+'的消息找到你，扣住了送补给的船。他们要求交出宝物，船上的人等你回应。';
  if(id==='trial_echo')return '陶宁寄回当年的姓名牌。他'+(mate==='missing'?'已经从封闭侧门脱身，找到你的地址。':'正在带领后来入谷的弟子。')+'旧阵又困住了一队人，他问你是否能帮忙查路与接应。';
  return typeof node.text==='function'?node.text(s):node.text;
}
